"""Cuaderno del estudiante, 3.º medio Lengua y Literatura FG, OAC 08 (diálogo argumentativo para construir y ampliar ideas).

Todos los textos literarios y diálogos son originales e inventados; cada ejercicio trae escrito el texto que necesita.
Los textos reales que se discutan en clase quedan a cargo del docente.
"""
from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from fg_leli_common import L, E, arith  # noqa: E402,F401

OA = "FG-LELI-3M-OAC-08"


def AB(q, right, wrong, why):
    """Pregunta de dos alternativas; la correcta se escribe primero y el registro la reubica."""
    return E(f"{q} A) {right} B) {wrong}", f"A) {right}", why)


# Textos originales de apoyo (inventados)
ZORRO = "«Un zorro guardó en secreto un cántaro de miel. Cuando llegó el invierno, la repartió entre los animales que no habían guardado nada, pero les pidió que, a cambio, lo defendieran de las tormentas.»"
PUERTA = "«Dejé la puerta abierta toda la noche / por si volvías con el viento. / Al amanecer solo entró la luz, / con las manos vacías.»"
MONEDAS = "«Ema contó las monedas tres veces. Las guardó en la lata y dijo: “Todavía no alcanza”. Al otro día volvió a contarlas.»"

# ------------------------------------------------------------------ clase 1
L(OA, 1,
  "Aprenderé a explicar el criterio de análisis, el razonamiento y la conclusión de una postura provisional sobre un texto literario, para dialogar con otras personas.",
  ["Puedo interpretar un cuento o un poema breve.", "Distingo un hecho de una opinión.", "Sé usar conectores como porque y por lo tanto."],
  ["En un diálogo argumentativo no basta con decir «a mí me parece». Para que otros puedan evaluar tu idea, debes mostrar tres partes. El criterio de análisis es el aspecto del texto que miras: las acciones de un personaje, una imagen, la voz del poema, el final. El razonamiento es el camino que une lo que observaste con tu idea («porque… entonces…»). La conclusión es la interpretación a la que llegas.",
   "Tu postura es provisional cuando la presentas como una lectura posible, abierta a cambiar si aparece una evidencia mejor. No es una debilidad: es honestidad intelectual. Se nota en frases como «por ahora concluyo que…», «mi lectura es que…», «puede que me falte considerar…». Una postura provisional no es vaga; sigue diciendo con claridad qué piensas y por qué.",
   "Un modelo útil para hablar es: «Mi criterio es mirar (aspecto). Observo que (dato del texto). Razono que (conexión). Por lo tanto, concluyo, por ahora, que (interpretación)». Con esta estructura, quien te escucha puede estar de acuerdo con tu criterio y discrepar en tu conclusión, o al revés. Así el diálogo se centra en razones, no en quién tiene la voz más fuerte."],
  [("criterio de análisis", "aspecto del texto que se observa para interpretarlo"), ("razonamiento", "conexión que explica por qué un dato lleva a una conclusión"), ("conclusión", "interpretación a la que se llega"), ("provisional", "que puede cambiar si aparece una razón o evidencia mejor")],
  [("Identificar las tres partes", f"Sobre el texto {ZORRO}, Lía dice: «Miro cuándo reparte la miel el zorro: solo en invierno, cuando los demás la necesitan. Entonces su generosidad tiene un momento estratégico. Concluyo, por ahora, que ayuda con interés». ¿Cuál es el criterio?",
    ["El criterio es el aspecto del texto que mira: el momento en que reparte la miel.", "El razonamiento es «entonces su generosidad tiene un momento estratégico».", "La conclusión es «ayuda con interés»."],
    "El momento en que el zorro reparte la miel"),
   ("Completar una postura incompleta", "Teo dice: «El zorro es egoísta». ¿Qué le falta?",
    ["Hay una conclusión, pero no se sabe qué observó.", "Falta un criterio y un dato del texto.", "Agrego: «Miro lo que pide a cambio: protección. Eso muestra interés personal; por ahora concluyo que su generosidad es condicionada»."],
    "Le falta criterio, evidencia y razonamiento")],
  [("Presentar la conclusión como la única posible.", "Cierra el diálogo y hace que el resto solo pueda aceptar o rechazar.", "Usa fórmulas provisionales y deja ver tu razonamiento."),
   ("Dar solo la conclusión sin el razonamiento.", "Nadie puede evaluar cómo llegaste a ella.", "Muestra qué observaste y cómo lo conectas con tu idea.")],
  ([AB("El criterio de análisis es", "el aspecto del texto que observas", "la nota que esperas obtener", "Es el punto de vista desde el cual lees el texto."),
    AB("Una postura provisional es", "una lectura posible que puede cambiar", "una opinión dicha con dudas, sin razones ni evidencia que la sostengan", "Provisional no es vaga: está abierta a ajustes."),
    E("Completa: la conexión que explica por qué un dato lleva a una conclusión es el ______.", "razonamiento", "El razonamiento une el dato con la conclusión.")],
   [AB(f"Texto: {PUERTA} Rosa dice: «Miro la puerta abierta toda la noche: muestra espera. Concluyo que el hablante conserva la esperanza». ¿Qué parte es la conclusión?", "el hablante conserva la esperanza", "miro la puerta abierta toda la noche", "La conclusión es la interpretación final; lo otro es el dato observado."),
    AB("¿Qué frase es una fórmula de postura provisional?", "«Por ahora, mi lectura es que el personaje duda»", "«Es absolutamente claro que el personaje duda»", "«Por ahora» indica que la lectura puede cambiar."),
    AB(f"Texto: {MONEDAS} Dani dice: «Ema es avara». ¿Qué le falta?", "mostrar qué observó y por qué lo concluye", "un tono más seguro y una conclusión todavía más tajante", "Falta el criterio y el razonamiento.")],
   [AB(f"Texto: {PUERTA} ¿Cuál afirmación incluye criterio, dato y razonamiento?", "«Observo que la luz llega “con las manos vacías”; eso muestra que nada vuelve; entonces la espera termina en pérdida»", "«Me parece que el poema es triste porque habla de una espera que no termina bien»", "La primera combina observación, conexión y conclusión."),
    AB(f"Texto: {MONEDAS} Lucas quiere presentar una lectura provisional. ¿Qué cierre elige?", "«Por ahora creo que Ema teme no alcanzar, aunque no descarto otra lectura»", "«Ema es ansiosa por naturaleza, y eso explica por completo el texto»", "La primera deja el diálogo abierto."),
    AB("Quieres mostrar tu criterio antes de dar la conclusión. ¿Cómo comienzas?", "«Mi criterio es mirar el final del texto»", "«Mi conclusión es que el final es triste»", "El criterio indica desde dónde observas.")],
   [AB(f"Texto: {ZORRO} Ana: «El zorro es generoso». Beto: «Mira lo que pide a cambio: defensa. Entonces su generosidad es condicionada». ¿Qué aporta Beto?", "un dato del texto y un razonamiento", "una opinión más extensa y mejor escrita", "Cita lo que pide a cambio y lo conecta con su idea."),
    AB("Ema dice «Esto es así y punto». ¿Qué falla en términos de diálogo argumentativo?", "no muestra razones que otros puedan evaluar", "usa un tono demasiado cortés con las demás personas", "Sin razones no hay argumento.")],
   [AB(f"Texto: {MONEDAS} Gina dice: «Miro las acciones repetidas de Ema: cuenta varias veces. Razono que no logra tranquilizarse. Concluyo que le preocupa el dinero». ¿Cuál es el criterio de Gina?", "las acciones repetidas de Ema", "que le preocupa el dinero", "El criterio es el aspecto del texto que mira, no la conclusión."),
    arith("Una postura de ejemplo se explica en 3 partes de 2 oraciones cada una, y 1 oración más de cierre provisional. ¿Cuántas oraciones tiene en total?", "3 * 2 + 1", "Se suman las oraciones de las tres partes y la del cierre.")]),
  [AB(f"Texto: {ZORRO} En clase, Jazmín dice: «Mi criterio es el final: el zorro pide algo a cambio. Razono que su ayuda no es gratuita. Por ahora concluyo que su generosidad es interesada». ¿Qué hace que su postura sea dialogable?", "da criterio, razonamiento y conclusión provisional", "es una opinión muy segura, expresada con claridad y sin dudas", "Permite que otros evalúen cada parte.")],
  [AB("¿Qué parte de la postura responde a «¿qué miré?»", "el criterio", "la conclusión", "El criterio es el aspecto observado."),
   AB("¿Qué significa «por ahora» en una conclusión?", "que puede ajustarse con nueva evidencia", "que la conclusión es menos importante que las otras partes", "Marca la provisoriedad."),
   E("Escribe el nombre de la parte que une dato y conclusión: ______.", "razonamiento", "Une lo observado con lo que se concluye.")],
  (f"Lee este texto original: {PUERTA}. Escribe tu postura provisional en 4 a 6 líneas con la estructura: «Mi criterio es… Observo que… Razono que… Por ahora concluyo que…». Usa una palabra o verso del poema como dato.",
   "Mi criterio es mirar el último verso. Observo que la luz entra «con las manos vacías». Razono que, si la luz no trae a nadie, lo que se esperaba no llegó. Por ahora concluyo que el poema habla de una espera que se frustra, aunque la puerta abierta podría mostrar que aún hay cierta esperanza.",
   ["criterio explícito", "dato del texto", "razonamiento", "conclusión provisional"], ["texto de cuatro a seis líneas en el cuaderno"], ["conclusión sin dato", "dato sin conexión", "tono categórico"],
   "Subraya con tres colores criterio, razonamiento y conclusión y comprueba que estén las tres."),
  "Explica en voz alta a alguien de tu casa tu postura sobre un cuento, usando las cuatro frases del modelo.",
  "Escribe una segunda postura provisional sobre el mismo poema con otro criterio.")

# ------------------------------------------------------------------ clase 2
L(OA, 2,
  "Aprenderé a elegir evidencia pertinente y suficiente del texto para fundamentar una postura y para sostenerla en un diálogo.",
  ["Presento un criterio, un razonamiento y una conclusión.", "Sé citar una frase de un texto.", "Distingo cita textual y paráfrasis."],
  ["Evidencia es lo que está en el texto (o en otra fuente disponible) y respalda lo que afirmas: una cita textual entre comillas, una acción de un personaje, una imagen o un dato. No es evidencia tu opinión ni lo que «te da la impresión». Una evidencia es pertinente si se relaciona de manera directa con tu afirmación; si la cita habla de otra cosa, no sirve aunque sea bonita.",
   "Es suficiente cuando alcanza para sostener la conclusión sin dejar dudas razonables. Una sola cita puede bastar si es muy clara, o puede ser insuficiente si la afirmación es amplia. Una regla práctica: cuanto más general es lo que afirmas, más evidencia necesitas. Además, la evidencia no debe contradecir otras partes del texto: si hay otro pasaje que lleva a otra lectura, hay que reconocerlo.",
   "Después de citar, explica. La estructura es: afirmación, evidencia y comentario. «Ema vive pendiente de lo que le falta. En el texto cuenta las monedas “tres veces” y vuelve a contarlas al otro día. Esa repetición muestra que no logra tranquilizarse». En un diálogo, pedir evidencia a otros («¿en qué parte del texto lo ves?») es una forma respetuosa de ayudar a precisar ideas."],
  [("evidencia", "dato, cita o hecho del texto que respalda una afirmación"), ("pertinente", "relacionada directamente con lo que se afirma"), ("suficiente", "que alcanza para sostener la conclusión"), ("comentario", "explicación de cómo la evidencia apoya la afirmación")],
  [("Evaluar si la evidencia es pertinente", f"Afirmación: «Ema siente inseguridad por el dinero». Texto: {MONEDAS} Evidencia propuesta: «La lata donde guarda las monedas». ¿Es pertinente?",
    ["La lata muestra dónde guarda, pero no la inseguridad.", "Las acciones de contar tres veces y de volver a contar sí la muestran.", "La evidencia de la lata no es pertinente por sí sola."],
    "No es pertinente; sirven las acciones de contar varias veces"),
   ("Armar afirmación, evidencia y comentario", f"Texto: {ZORRO} Afirmación: «El zorro reparte la miel con una condición».",
    ["Evidencia: les pidió que, a cambio, lo defendieran de las tormentas.", "Comentario: esa petición muestra que su ayuda no es gratuita.", "Uno la evidencia con la afirmación mediante «esto muestra que»."],
    "Se cita el pedido a cambio y se explica que la ayuda tiene condición")],
  [("Copiar una cita larga sin explicar para qué sirve.", "El lector no sabe qué parte importa ni cómo apoya tu idea.", "Cita lo necesario y agrega un comentario."),
   ("Usar una sola cita para una afirmación muy amplia.", "Una afirmación general necesita más respaldo.", "Reúne más de una evidencia o reduce lo que afirmas.")],
  ([AB("La evidencia pertinente es la que", "se relaciona directamente con lo afirmado", "es la que ocupa más líneas en el texto", "La relación directa con la afirmación es lo que importa."),
    AB("Una opinión personal sin referencia al texto es", "un juicio, no evidencia", "una evidencia suficiente", "La evidencia debe estar en el texto."),
    E("Completa: la explicación de cómo una cita apoya la afirmación es el ______.", "comentario", "El comentario conecta cita y afirmación.")],
   [AB(f"Afirmación: «La hablante conserva esperanza». Texto: {PUERTA} ¿Qué evidencia es pertinente?", "“Dejé la puerta abierta toda la noche”", "“con las manos vacías”", "La puerta abierta muestra disposición a esperar; las manos vacías indican pérdida."),
    AB("Quieres afirmar algo amplio: «el narrador desconfía de todos los personajes». ¿Qué necesitas?", "más de una evidencia de distintos momentos", "una sola cita muy clara que te guste mucho", "A mayor generalidad, más evidencia."),
    AB("Estructura correcta de un fragmento argumentativo:", "afirmación, evidencia y comentario", "comentario, evidencia y despedida", "Esa es la secuencia que une idea y texto.")],
   [AB(f"Texto: {MONEDAS} Afirmación: «Ema no se conforma con contar una vez». ¿Qué evidencia es suficiente?", "contó tres veces y volvió a contarlas al otro día", "dijo “todavía no alcanza” y guardó las monedas en la lata", "Las repeticiones respaldan directamente que no se conforma."),
    AB(f"Texto: {ZORRO} Un estudiante dice: «El zorro es malo». Pide evidencia, de manera respetuosa. ¿Qué pregunta haces?", "«¿En qué parte del texto ves eso?»", "«¿Cómo se te ocurre semejante idea?»", "La primera solicita evidencia sin descalificar."),
    AB(f"Texto: {PUERTA} Un compañero afirma: «El poema habla de la alegría». ¿Qué problema tiene la evidencia “con las manos vacías”?", "contradice la afirmación", "no tiene ninguno, porque las manos vacías también sugieren alegría", "Las manos vacías sugieren carencia, no alegría.")],
   [AB(f"Texto: {ZORRO} Dos estudiantes. Pía: «El zorro es avaro». Evidencia: “guardó en secreto un cántaro de miel”. Iván: «El zorro es avaro». Evidencia: “la repartió entre los animales”. ¿Qué ocurre?", "la evidencia de Pía apoya parcialmente; la de Iván la contradice", "ambas apoyan por igual, porque las dos citan una acción del zorro", "Repartir la miel va contra la idea de avaricia."),
    AB(f"Texto: {MONEDAS} Una compañera cita una frase y no la comenta. ¿Qué le sugieres?", "explicar cómo esa frase apoya su idea", "eliminar la cita y quedarse solo con la afirmación", "Sin comentario la cita queda suelta.")],
   [AB(f"Texto: {ZORRO} Afirmación: «La generosidad del zorro es condicionada y planificada». Evidencias: (1) la guardó en secreto; (2) la repartió en invierno; (3) pidió defensa a cambio. ¿Cuántas evidencias apoyan que sea planificada y condicionada?", "las tres", "solo la última", "Guardar, esperar al invierno y pedir algo a cambio muestran planificación y condición."),
    arith("Quieres sostener una afirmación amplia con 3 evidencias, cada una con un comentario de 2 oraciones y una cita de 1 oración. ¿Cuántas oraciones necesitas en total?", "3 * (2 + 1)", "Cada evidencia ocupa 3 oraciones y son tres.")]),
  [AB(f"Texto: {MONEDAS} Quieres sostener que «Ema vive pendiente de lo que le falta». ¿Qué combinación es mejor?", "citar “Todavía no alcanza” y que vuelve a contarlas, con un comentario", "mencionar que Ema guarda las monedas en una lata y las cuenta", "Las acciones y la frase respaldan lo que le falta.")],
  [AB("¿Qué es una evidencia suficiente?", "la que alcanza para sostener la conclusión", "la que ocupa más líneas del comentario escrito", "Basta para respaldar lo afirmado."),
   AB("¿Qué se hace tras citar?", "se comenta la cita", "se pasa a otro tema", "El comentario relaciona cita y afirmación."),
   E("Escribe qué palabra se aplica a la evidencia relacionada directamente con la idea: ______.", "pertinente", "Pertinente es lo relacionado directamente.")],
  (f"Texto original: {ZORRO}. Escribe un párrafo de 5 a 7 líneas con: a) una afirmación sobre el zorro; b) dos evidencias del texto entre comillas; c) un comentario que conecte cada evidencia con la afirmación; d) una frase provisional de cierre.",
   "Afirmación: el zorro reparte la miel con un propósito. Evidencia 1: la repartió «cuando llegó el invierno», cuando era más necesaria. Comentario: eligió el momento de mayor necesidad. Evidencia 2: les pidió «que lo defendieran de las tormentas». Comentario: su ayuda tiene precio. Cierre: por ahora, creo que su generosidad es interesada.",
   ["afirmación clara", "dos evidencias pertinentes", "comentarios", "cierre provisional"], ["párrafo en el cuaderno"], ["cita sin comentario", "evidencia que contradice", "una sola evidencia"],
   "Revisa que cada comillas tenga un comentario que explique su función."),
  "Elige una frase de un texto que leas hoy y escribe qué afirmación podría respaldar.",
  "Busca una evidencia que contradiga tu afirmación y explica cómo cambiarías tu postura.")

# ------------------------------------------------------------------ clase 3
L(OA, 3,
  "Aprenderé a parafrasear la posición de otra persona de forma fiel antes de evaluarla, para dialogar sin descalificar ni deformar sus ideas.",
  ["Sé exponer mi postura con criterio, razonamiento y conclusión.", "Escucho sin interrumpir.", "Distingo una idea de la persona que la dice."],
  ["Parafrasear es decir con palabras propias lo que otra persona dijo. En un diálogo argumentativo se hace antes de evaluar o refutar: «Si entiendo bien, sostienes que… porque… ¿es así?». Esto cumple dos funciones. Primero, comprueba que entendiste. Segundo, muestra respeto, porque la otra persona ve que su idea fue escuchada con atención.",
   "Una paráfrasis es fiel cuando conserva la idea central, las razones y el grado de seguridad de quien habló. Se vuelve infiel si exagera («tú dices que todo es inútil»), si omite la razón, si agrega una intención que no dijo o si cambia «puede ser» por «seguro». Una forma común de infidelidad es la caricatura: presentar la idea del otro de manera tan extrema que sea fácil de rechazar.",
   "Después de parafrasear, espera la confirmación. Si la otra persona dice «no exactamente», ajustas. Solo entonces evalúas: «Estoy de acuerdo con tu criterio, pero tengo una duda sobre tu conclusión». Evaluar una posición sin haberla parafraseado fielmente suele llevar a discutir contra algo que nadie dijo. Y recuerda: se evalúan ideas y razones, no se descalifica a las personas ni se les atribuyen prejuicios."],
  [("paráfrasis fiel", "reformulación que conserva la idea central, las razones y la seguridad del original"), ("caricatura", "presentación exagerada de la idea de otro para que sea fácil de rechazar"), ("verificar", "comprobar que se entendió, preguntando a la otra persona"), ("atribuir", "decir que alguien dijo o pensó algo")],
  [("Elegir la paráfrasis fiel", "Mati dice: «Creo que el final del cuento podría leerse como una despedida, porque el personaje deja las llaves sobre la mesa». ¿Cuál paráfrasis es fiel?",
    ["Conserva «podría leerse» (no es seguro).", "Conserva la razón: deja las llaves.", "Fiel: «Propones que el final puede leerse como una despedida, porque el personaje deja las llaves»."],
    "Propones que el final puede leerse como una despedida, porque deja las llaves"),
   ("Detectar una caricatura", "Mati dice: «Podría haber algo de despedida en el final». Nora responde: «Dices que todo el cuento es una despedida y nada más». ¿Qué falla?",
    ["Mati dijo «podría haber algo».", "Nora lo convirtió en «todo» y «nada más».", "Es una caricatura: exagera la idea."],
    "Es una caricatura que exagera la idea")],
  [("Parafrasear cambiando el grado de seguridad («podría» por «seguro»).", "Se modifica la postura original y se discute otra idea.", "Conserva los matices de quien habló."),
   ("Empezar a refutar sin comprobar que entendiste.", "Puedes estar refutando algo que la otra persona no dijo.", "Parafrasea, pregunta si es así y luego evalúa.")],
  ([AB("Parafrasear es", "decir con tus palabras lo que dijo otra persona", "repetir sus mismas palabras, en el mismo orden, con tono de duda", "Se reformula con palabras propias."),
    AB("Una caricatura de una idea", "la exagera para que sea fácil rechazarla", "la presenta tal como es, con sus razones y matices", "Deforma la idea."),
    E("Completa: «Si ______ bien, sostienes que…» es una forma de iniciar una paráfrasis.", "entiendo", "La expresión pide confirmar la comprensión.")],
   [AB("Dani: «Tal vez el personaje miente, porque cambia su versión dos veces». ¿Cuál paráfrasis es fiel?", "«Planteas que tal vez miente, porque cambia su versión»", "«Dices que el personaje es un mentiroso total»", "La fiel conserva «tal vez» y la razón."),
    AB("Después de parafrasear, ¿qué conviene hacer?", "preguntar si lo entendiste bien", "pasar directo a refutar para no perder el turno", "La verificación evita deformar."),
    AB("¿Cuál paráfrasis omite la razón?", "«Dices que el final es esperanzador»", "«Dices que el final es esperanzador porque sale el sol»", "La primera no incluye el porqué.")],
   [AB("Eli: «Quizás el poema critica el olvido». Rita: «O sea, tú piensas que nadie recuerda nada». ¿Qué problema hay?", "Rita exagera y cambia el sentido", "Rita parafrasea fielmente", "Cambió «quizás» por una afirmación absoluta."),
    AB("Frente a «No exactamente, dije otra cosa», lo más adecuado es", "ajustar tu paráfrasis y volver a preguntar", "insistir en tu versión, porque ya la habías pensado bien", "Corregir la comprensión es parte del diálogo."),
    AB("Iván dice: «Creo que el narrador es poco confiable porque se contradice». ¿Cuál es una paráfrasis fiel?", "«Sostienes que el narrador no es confiable, porque se contradice»", "«Dices que el narrador es poco confiable, aunque no des razones»", "Conserva la idea y la razón; no agrega «siempre».")],
   [AB("Un compañero te pone en tu boca una idea extrema que no dijiste. ¿Qué respuesta es más dialogante?", "«No dije eso. Mi idea es esta: …»", "«Eres injusto y no entiendes nada»", "Aclarar tu idea evita la descalificación."),
    AB("Quieres rebatir una postura que te parece débil. ¿Qué haces primero?", "parafrasearla en su forma más sólida y fiel", "señalar que quien la dice se equivoca siempre", "Se discute la mejor versión de la idea.")],
   [AB("Natalia: «Creo que el cuento defiende la honestidad, aunque quizás con matices». Tú: «Dices que defiende la honestidad». ¿Qué mejora necesita tu paráfrasis?", "incluir «con matices»", "agregar tu opinión", "Falta conservar el matiz."),
    arith("Una paráfrasis fiel de ejemplo tiene 3 partes: idea, razón y grado de seguridad. En un diálogo parafraseas 4 posturas distintas. ¿Cuántos elementos debes verificar en total?", "4 * 3", "Cada postura tiene tres partes y son cuatro.")]),
  [AB("Camila: «Podría ser que la protagonista no quiere irse, porque guarda la maleta vacía». Para verificar tu comprensión, ¿qué dices?", "«Si entiendo bien, propones que quizá no quiere irse, por la maleta vacía; ¿es así?»", "«Seguro piensas que la protagonista no quiere irse y que lo tiene decidido»", "Parafrasea con matices y comprueba.")],
  [AB("¿Qué conserva una paráfrasis fiel?", "la idea, las razones y la seguridad", "solo el tono y las palabras exactas del original", "Son los tres componentes."),
   AB("¿Para qué sirve preguntar «¿es así?»", "para verificar la comprensión", "para ganar tiempo antes de responder", "Permite que la otra persona corrija."),
   E("Escribe el nombre de la presentación exagerada de una idea ajena: ______.", "caricatura", "Es el término de la clase.")],
  ("Lee esta postura de ejemplo: «Creo que en el poema de la puerta abierta el hablante podría estar esperando a alguien, porque deja la puerta abierta toda la noche. No estoy seguro de que sea una persona». Escribe: a) una paráfrasis fiel de 2 a 3 líneas; b) una versión caricaturizada, rotulada «caricatura»; c) qué pregunta harías para verificar.",
   "a) Si entiendo bien, propones que el hablante podría estar esperando a alguien, por la puerta abierta toda la noche, aunque no estás seguro de que sea una persona. b) Caricatura: dices que seguro espera a su pareja y que no hay otra lectura. c) ¿Es así o me falta algún matiz?",
   ["paráfrasis fiel", "caricatura reconocible", "pregunta de verificación", "conserva el matiz"], ["tres respuestas en el cuaderno"], ["agregar intención", "perder el matiz", "omitir la razón"],
   "Compara tu paráfrasis con el original y marca si conserva idea, razón y seguridad."),
  "Parafrasea en una línea una opinión que hayas oído hoy y pregúntale a la persona si la entendiste.",
  "Escribe una paráfrasis fiel de una postura con la que no estés de acuerdo.")

# ------------------------------------------------------------------ clase 4
L(OA, 4,
  "Aprenderé a examinar las premisas, las relaciones entre ideas, las elecciones de palabras y los énfasis de un razonamiento ajeno, para evaluarlo con criterio.",
  ["Parafraseo posturas de manera fiel.", "Reconozco conectores de causa y consecuencia.", "Identifico palabras valorativas."],
  ["Evaluar el razonamiento de otra persona es examinar cómo está construido. Las premisas son las ideas que se aceptan como punto de partida: «las acciones repetidas muestran un rasgo del personaje». Pueden estar dichas (explícitas) o quedar sin decir (implícitas). Una conclusión es débil si depende de una premisa implícita discutible. Pregúntate: ¿qué se supone aquí para que la conclusión valga?",
   "También se examinan las relaciones entre las ideas: causa («porque»), condición («si… entonces»), ejemplo que se generaliza, oposición. Se revisa si la conclusión realmente se sigue. Algunos errores comunes son la generalización apresurada (de un caso a «todos»), el falso dilema (presentar solo dos opciones cuando hay más) y el ataque a la persona (en lugar de refutar la idea, se critica a quien la dice). Detectarlos permite responder con razones.",
   "Las elecciones de palabras y los énfasis también cuentan: «evidentemente», «obviamente» o «es un fracaso total» presionan al oyente sin aportar razones. La repetición, el orden y los adjetivos intensos destacan ciertas ideas y esconden otras. Evaluar no es buscar errores para ganar, sino entender qué sostiene la conclusión y cuánto la sostiene. Y se hace con respeto: «No veo que esa premisa esté en el texto, ¿en qué te basas?»."],
  [("premisa", "idea que se acepta como base de un razonamiento"), ("premisa implícita", "premisa que no se dice pero se supone"), ("generalización apresurada", "pasar de unos pocos casos a una afirmación sobre todos"), ("falso dilema", "presentar solo dos opciones cuando existen más")],
  [("Detectar una premisa implícita", "Dani dice: «El personaje cierra la ventana, entonces es una persona cobarde». ¿Qué premisa implícita hay?",
    ["La conclusión es «cobarde».", "Para llegar ahí se supone que cerrar una ventana es señal de miedo.", "Esa premisa es discutible: podría ser frío, cuidado u otra cosa."],
    "Se supone que cerrar la ventana indica cobardía"),
   ("Reconocer un falso dilema", "«O el narrador dice la verdad, o el cuento no tiene sentido». ¿Qué falla?",
    ["Presenta solo dos opciones.", "Hay otras: el narrador puede ser poco confiable y el cuento tener sentido igual.", "Es un falso dilema."],
    "Falso dilema: omite otras posibilidades")],
  [("Rechazar una idea porque «lo dijo alguien que no me cae bien».", "Se ataca a la persona y no al razonamiento.", "Evalúa las premisas y las relaciones de la idea."),
   ("Aceptar una conclusión solo porque suena muy segura.", "La seguridad del tono no es evidencia.", "Busca premisas y evidencia que la sostengan.")],
  ([AB("Una premisa es", "una idea que se acepta como base", "la conclusión final a la que llega el razonamiento", "Es el punto de partida."),
    AB("Una generalización apresurada pasa de", "uno o pocos casos a «todos»", "muchos casos a una conclusión prudente", "Generaliza sin suficiente base."),
    E("Escribe el nombre del error: criticar a quien dice una idea en lugar de la idea. Ataque a la ______.", "persona", "Se critica a la persona y no a su razonamiento.")],
   [AB("«Dos personajes mienten, así que todos los personajes del cuento mienten». Esto es", "una generalización apresurada", "un razonamiento sólido, porque usa dos ejemplos", "Dos casos no bastan para afirmar «todos»."),
    AB("«O estás de acuerdo conmigo o no entendiste el cuento». Esto es", "un falso dilema", "una paráfrasis fiel", "Reduce las posibilidades a dos."),
    AB("¿Qué palabra presiona sin aportar razones?", "«obviamente»", "«porque»", "«Obviamente» da por hecho sin justificar.")],
   [AB("Nico: «La ventana cerrada prueba que el personaje es frío». ¿Cuál es una pregunta crítica adecuada?", "«¿Por qué una ventana cerrada indicaría frialdad?»", "«¿Cómo puedes ser tan ingenuo para pensar así?»", "Pide la premisa sin atacar."),
    AB("Eva: «Tres de las cuatro escenas ocurren de noche, entonces el cuento trata del miedo». ¿Qué premisa implícita se supone?", "que la noche se asocia al miedo", "que el cuento tiene cuatro escenas", "Se supone una asociación noche-miedo."),
    AB("«Esa interpretación es un error absoluto». Los términos «error absoluto» son", "una elección de palabras cargada", "una evidencia tomada del texto citado", "Presionan sin dar razones.")],
   [AB("«Como el narrador es un niño, nada de lo que dice es creíble». ¿Qué problema tiene?", "generaliza a «nada» desde una característica", "es una premisa explícita razonable", "Pasa de una característica a una conclusión extrema."),
    AB("Ema dice: «Si el protagonista es egoísta, entonces el final es un castigo». ¿Qué relación usa?", "una condición", "una oposición", "Usa el esquema si… entonces.")],
   [AB("Lía: «El poema habla de la pérdida: la luz entra “con las manos vacías”». Ben: «Lía siempre ve tristeza en todo». ¿Qué hace Ben?", "ataca a la persona en vez de la idea", "evalúa la premisa y la relación con la conclusión", "No discute la evidencia."),
    arith("Una conclusión se apoya en 3 premisas. Si 1 de ellas es implícita y la revisas, ¿cuántas premisas explícitas hay?", "3 - 1", "Se resta la premisa implícita del total.")]),
  [AB("Dani: «El protagonista nunca llama a nadie, entonces odia a las personas». ¿Qué premisa implícita es la más discutible?", "que no llamar equivale a odiar", "que existe un protagonista", "Es el salto entre una conducta y un sentimiento.")],
  [AB("¿Qué examinas en las premisas?", "si son aceptables y suficientes", "cuántas son y cuán largas son", "Se evalúa su solidez."),
   AB("«Evidentemente…» al inicio de una frase puede ser", "una presión sin razones", "una evidencia fuerte que respalda la idea", "Pide aceptar sin justificar."),
   E("Completa: pasar de uno o dos casos a «todos» es una ______ apresurada.", "generalización", "Es el error de generalizar sin suficiente base.")],
  ("Lee este razonamiento de ejemplo: «El protagonista del cuento rompe su promesa una vez. Obviamente es una persona sin palabra. O se defiende la promesa o se acepta que nada importa». Escribe: a) una premisa implícita; b) un error de razonamiento (generalización apresurada o falso dilema) y por qué; c) una palabra con presión; d) cómo preguntarías a la persona para pedirle más razones, sin descalificarla.",
   "a) Se supone que romper una promesa una vez define a una persona. b) Falso dilema: ofrece solo dos opciones cuando hay otras. c) «Obviamente». d) «¿Qué otras acciones del protagonista muestran que no cumple su palabra?».",
   ["premisa implícita", "error identificado y explicado", "palabra cargada", "pregunta respetuosa"], ["cuatro respuestas en el cuaderno"], ["llamar al otro «ingenuo»", "no explicar el error", "confundir premisa y conclusión"],
   "Revisa que tu pregunta pida razones y no ataque a la persona."),
  "Escribe una premisa implícita de una frase que hayas oído hoy.",
  "Redacta una frase con generalización apresurada y luego corrígela.")

# ------------------------------------------------------------------ clase 5
L(OA, 5,
  "Aprenderé a ampliar o refutar las ideas de mis pares, incorporando sus aportes con razones y evidencia.",
  ["Parafraseo fielmente.", "Examino premisas y relaciones.", "Fundamento con evidencia del texto."],
  ["Incorporar la posición de un par significa hacerla parte de tu razonamiento, no solo esperar tu turno. Hay dos caminos principales. Ampliar es sumar algo: otra evidencia, un matiz, una conexión con otra parte del texto o una consecuencia. Refutar es mostrar, con razones, que una idea tiene un punto débil: la premisa no se sostiene, hay evidencia que la contradice o la conclusión no se sigue de lo que se dijo.",
   "Para ampliar puedes decir: «Coincido contigo y agrego que…», «Eso se relaciona con…». Para refutar: «Entiendo que piensas que…; sin embargo, el texto dice… y por eso creo que…». Una refutación sólida identifica con precisión qué parte refuta (premisa, evidencia o conclusión), da una razón y, si es posible, ofrece una alternativa. Refutar una idea nunca autoriza a burlarse de quien la dijo.",
   "A veces tras escuchar cambias de postura. Eso no es perder, es aprender. Lo importante es decir qué te hizo cambiar: «Con la cita que mencionaste, ahora veo que mi lectura era incompleta». El diálogo argumentativo construye ideas entre varias personas: lo que cada uno aporta mejora lo que había antes. Por eso conviene registrar quién propuso qué para reconocer los aportes."],
  [("ampliar", "sumar evidencia, matices o conexiones a la idea de otro"), ("refutar", "mostrar con razones que una idea tiene un punto débil"), ("matiz", "precisión que limita o afina una afirmación"), ("contraevidencia", "dato o cita que contradice una afirmación")],
  [("Ampliar el aporte de un par", f"Rita dice sobre {MONEDAS}: «Ema parece ansiosa porque cuenta varias veces». ¿Cómo amplías?",
    ["Coincido con la idea de Rita.", "Agrego otro dato: dice “todavía no alcanza” antes de volver a contar.", "«Coincido y agrego que su frase “todavía no alcanza” muestra que cuenta por lo que le falta»."],
    "Se suma una evidencia nueva que refuerza la idea"),
   ("Refutar con una contraevidencia", f"Teo dice sobre {ZORRO}: «El zorro es egoísta porque guarda la miel en secreto». ¿Cómo refutas?",
    ["Entiendo su razón: guarda en secreto.", "Pero el texto dice que después la reparte.", "«Entiendo, pero luego reparte la miel; quizá no sea egoísta, aunque su ayuda tiene condición»."],
    "Se usa la contraevidencia: reparte la miel")],
  [("Refutar con «eso no es así» sin dar razones.", "No se sabe qué parte se refuta ni por qué.", "Señala qué premisa o evidencia falla y da una razón."),
   ("Ampliar repitiendo lo que dijo el otro.", "No aporta nada nuevo.", "Suma una evidencia, un matiz o una conexión.")],
  ([AB("Ampliar una idea es", "sumar evidencia o matices", "repetir la idea con otras palabras", "Se agrega algo nuevo."),
    AB("Refutar es", "mostrar con razones un punto débil", "burlarse de quien habla con ironía suave", "Se basa en razones."),
    E("Completa: un dato que contradice una afirmación es una ______.", "contraevidencia", "Contraevidencia: evidencia contraria.")],
   [AB("Una forma de ampliar es", "«Coincido y agrego que…»", "«Eso no vale, no tiene sentido»", "Reconoce y suma."),
    AB("Una refutación sólida identifica", "qué parte de la idea refuta", "quién la dijo y qué opinión tiene de ella", "La parte puede ser premisa, evidencia o conclusión."),
    AB(f"Texto: {PUERTA} Lía: «Hay esperanza porque deja la puerta abierta». Sumas otro dato: «por si volvías con el viento». ¿Qué haces?", "amplías con otro dato del texto", "refutas la idea, porque ahora hay otro dato", "Aportas algo que se relaciona con su idea.")],
   [AB(f"Texto: {ZORRO} Nico: «El zorro es solidario». Tú notas que pide algo a cambio. ¿Qué refutación es mejor?", "«Entiendo, pero pide protección a cambio; podría ser solidaridad con condición»", "«Estás equivocado, el zorro nunca fue solidario»", "Da una razón concreta y matiza."),
    AB(f"Texto: {MONEDAS} Mica dice: «Ema es ordenada porque guarda las monedas». ¿Qué aporte amplía su idea?", "«Y las cuenta varias veces, lo que refuerza su orden o su preocupación»", "«Y Ema es un nombre que se usa mucho en los cuentos»", "Agrega un dato pertinente."),
    AB("Alguien te aporta una cita que contradice tu idea. ¿Qué actitud es adecuada?", "revisar tu postura y decir qué cambió", "ignorar la cita, porque tu idea ya estaba escrita", "Incorporar la evidencia mejora el diálogo.")],
   [AB("Dos refutaciones. Ana: «Esa premisa no se sostiene porque no hay cita». Beto: «Tú nunca entiendes nada». ¿Cuál es adecuada?", "la de Ana", "la de Beto", "Identifica un punto débil con razón."),
    AB("Un compañero te convence con una cita. ¿Qué frase cierra bien?", "«Con esa cita, mi lectura era incompleta»", "«Igual sigo pensando lo mismo, aunque no sé por qué»", "Reconoce el aporte y explica el cambio.")],
   [AB(f"Texto: {PUERTA} Dos estudiantes: Julia: «Es esperanza». Mario: «Es pérdida». ¿Qué aporte construye una lectura más amplia?", "«Podría ser ambas: la puerta abierta muestra esperanza y las manos vacías, pérdida»", "«Mario tiene razón, porque la pérdida pesa más que la esperanza»", "Integra ambas evidencias."),
    arith("En una discusión de ejemplo, 4 personas aportan 2 evidencias cada una, pero 3 de esas evidencias repiten otra ya dicha. ¿Cuántas evidencias distintas hay?", "4 * 2 - 3", "Se calcula el total y se descuentan las repetidas.")]),
  [AB(f"Texto: {ZORRO} Tú piensas que el zorro es astuto; Leo dice que es prudente. ¿Qué aporte amplía la conversación?", "«Quizá ambas lecturas se complementan: guarda con prudencia y reparte con astucia»", "«Leo no sabe leer bien, porque el zorro es claramente astuto»", "Integra ambas lecturas.")],
  [AB("¿Qué se dice al ampliar?", "«Coincido y agrego»", "«No digas eso, no estoy de acuerdo»", "Es una fórmula de ampliación."),
   AB("Refutar a una persona es", "un error de diálogo argumentativo", "lo que se espera en un buen diálogo", "Se refuta la idea, no a la persona."),
   E("Escribe el nombre de la precisión que limita o afina una afirmación: ______.", "matiz", "El matiz afina la idea.")],
  (f"Lee este diálogo original. Poema: {PUERTA} Bea: «La hablante conserva esperanza». Ciro: «No, porque al final “solo entró la luz, con las manos vacías”». Escribe: a) una frase que amplíe la idea de Bea con otro dato; b) una frase que refute la idea de Ciro con una razón, sin descalificarlo; c) una frase de integración que mencione a ambos.",
   "a) Coincido con Bea y agrego que dejar la puerta abierta «toda la noche» muestra constancia. b) Entiendo a Ciro, pero «solo entró la luz» también puede ser un comienzo, no solo una pérdida. c) Entre Bea y Ciro podríamos decir que el poema mezcla espera y pérdida.",
   ["amplía con dato nuevo", "refuta con razón", "integra a ambos", "respeta a las personas"], ["tres frases en el cuaderno"], ["repetir lo mismo", "refutar sin razón", "burlarse"],
   "Marca en cada frase el dato o la razón que usas."),
  "Practica con una persona de tu casa: comenta una frase suya con «Coincido y agrego».",
  "Escribe una refutación y una ampliación a la misma idea.")

# ------------------------------------------------------------------ clase 6
L(OA, 6,
  "Aprenderé a cerrar un diálogo argumentativo con acuerdos, desacuerdos razonados y nuevas preguntas, registrando cómo se amplió o cambió cada postura.",
  ["Parafraseo, evalúo y refuto con respeto.", "Sé que una interpretación puede ser válida aunque sea distinta.", "Conozco la diferencia entre opinión y error de lectura."],
  ["Un diálogo argumentativo no tiene que terminar con un ganador. Tiene que dejar algo construido. El cierre reúne tres cosas: los acuerdos (lo que el grupo comparte), los desacuerdos razonados (dónde difieren y por qué) y las nuevas preguntas (lo que quedó abierto). Un buen cierre permite que cada persona diga cómo cambió, o no, su postura y por qué.",
   "Conviene distinguir los tipos de desacuerdo. Hay desacuerdos interpretativos: dos lecturas distintas, ambas respaldadas por el texto (por ejemplo, ver en un final esperanza o resignación). Y hay errores de lectura: afirmar algo que el texto contradice de forma clara (decir que un personaje murió si el texto no lo dice). Los primeros se sostienen con razones; los segundos se corrigen volviendo al texto.",
   "Para registrar el diálogo puedes usar un cuadro de tres columnas: acuerdos, desacuerdos razonados (con quién y con qué razón) y preguntas nuevas. Cierra con una frase como «Al comienzo pensaba… ahora pienso…». Si la conversación se puso tensa, vuelve a las razones y evita cerrar con ironías o reproches. Y si un tema te incomoda o recibes presión de otras personas, puedes hablarlo con un docente o con una persona adulta de confianza."],
  [("acuerdo", "idea que el grupo comparte"), ("desacuerdo razonado", "diferencia sostenida con razones y evidencia"), ("síntesis", "resumen que reúne lo principal de un diálogo"), ("error de lectura", "afirmación que el texto contradice claramente")],
  [("Distinguir tipo de desacuerdo", f"Texto: {PUERTA} Ana: «Es esperanza». Bruno: «Es pérdida». Ambos citan versos. ¿Qué tipo de desacuerdo es?",
    ["Ambos tienen respaldo en el texto.", "Son dos lecturas posibles.", "Es un desacuerdo interpretativo."],
    "Interpretativo"),
   ("Registrar un diálogo", f"Texto: {ZORRO} Tras el diálogo: acuerdan que el zorro reparte la miel; discrepan en si es interesado o prudente; una pregunta es «¿qué pasa si no hay tormentas?». ¿Qué categoría es cada cosa?",
    ["Lo que acuerdan: acuerdo.", "Lo que discrepan con razones: desacuerdo razonado.", "La pregunta: nueva pregunta."],
    "Acuerdo; desacuerdo razonado; nueva pregunta")],
  [("Cerrar diciendo «ganó el que tenía razón».", "Se pierde lo construido y se refuerza la idea de competir.", "Resume acuerdos, desacuerdos con razones y preguntas."),
   ("Tratar toda diferencia como si fuera un error de lectura.", "Se descalifican lecturas legítimas.", "Revisa si el texto respalda cada lectura antes de clasificar.")],
  ([AB("Un acuerdo es", "una idea que el grupo comparte", "una idea que cada integrante planteó por separado", "Es lo compartido."),
    AB("Un desacuerdo razonado", "tiene razones y evidencia", "se sostiene gritando", "Se apoya en razones."),
    E("Completa: el resumen que reúne lo principal de un diálogo es la ______.", "síntesis", "La síntesis resume lo principal.")],
   [AB(f"Texto: {MONEDAS} Dani dice que Ema perdió las monedas. ¿Qué tipo de error es?", "error de lectura, porque el texto no lo dice", "un desacuerdo interpretativo, porque hay dos lecturas posibles", "El texto no menciona pérdida."),
    AB("Una nueva pregunta tras un diálogo es", "algo que quedó abierto para seguir pensando", "una crítica a la persona que habló antes", "Abre un camino de indagación."),
    AB("Para registrar cómo cambió tu postura, ¿qué frase sirve?", "«Al comienzo pensaba…, ahora pienso… porque…»", "«Yo tenía razón desde el comienzo y se confirmó»", "Muestra el cambio y su razón.")],
   [AB(f"Texto: {PUERTA} Rita y Pablo discrepan: ella ve espera; él, resignación. Ambos citan versos. ¿Cómo se cierra bien?", "registrar ambas lecturas con sus razones y una pregunta nueva", "decidir cuál lectura tiene razón y descartar la otra", "El cierre reúne las dos lecturas."),
    AB(f"Texto: {ZORRO} Un compañero dice que el zorro castigó a los animales. ¿Cómo clasificas esa afirmación?", "error de lectura, porque el texto muestra que los ayudó", "un desacuerdo interpretativo, porque hay dos lecturas posibles", "El texto contradice esa afirmación."),
    AB("En un cuadro de tres columnas, ¿qué va en la tercera?", "preguntas nuevas", "acusaciones entre los integrantes", "Es la columna de lo abierto.")],
   [AB("Tras un diálogo, dos estudiantes tienen lecturas distintas respaldadas por el texto. ¿Qué conclusión es la más ajustada?", "ambas lecturas son válidas; el grupo puede comparar su fuerza", "una es correcta y la otra es un error de lectura", "Las dos tienen respaldo."),
    AB("Alguien insiste en burlarse de una compañera durante el cierre. ¿Qué haces?", "vuelves a las razones y, si continúa, avisas a un docente", "respondes con otra burla para equilibrar la situación", "Se protege la convivencia.")],
   [AB(f"Texto: {PUERTA} Un grupo concluye: «El poema es sobre la esperanza, porque la puerta está abierta; sobre la pérdida, por las manos vacías; queda abierta la pregunta: ¿qué volvía con el viento?». ¿Qué incluye este cierre?", "acuerdo, desacuerdos o lecturas y pregunta nueva", "una opinión y una crítica a otro estudiante", "Reúne las tres partes."),
    arith("En un diálogo de ejemplo se registran 3 acuerdos, 2 desacuerdos razonados y 4 preguntas nuevas. ¿Cuántas entradas tiene el registro?", "3 + 2 + 4", "Se suman las entradas de las tres columnas.")]),
  [AB(f"Texto: {MONEDAS} Tras debatir, un grupo escribe: «Ema siente ansiedad (acuerdo). Discrepamos si es por dinero o por tiempo (razones distintas)». ¿Qué falta para un buen cierre?", "una pregunta nueva que quedó abierta", "una burla amistosa para cerrar con humor", "Falta una pregunta para seguir.")],
  [AB("¿Qué incluye un buen cierre?", "acuerdos, desacuerdos razonados y preguntas", "solo las conclusiones de cada integrante", "Las tres partes."),
   AB("Un cambio de postura es", "algo legítimo si se explica", "una derrota que conviene ocultar", "Aprender también es parte del diálogo."),
   E("Escribe la palabra para la afirmación que el texto contradice: error de ______.", "lectura", "El texto muestra que no es así.")],
  ("Imagina que tu grupo dialogó sobre el cuento original del zorro. Escribe un cierre de 6 a 8 líneas con: a) dos acuerdos; b) un desacuerdo razonado con las razones de cada lado; c) una pregunta nueva; d) una frase tuya del tipo «Al comienzo pensaba… ahora pienso…».",
   "a) Acordamos que el zorro reparte la miel en invierno y pide algo a cambio. b) Julia ve interés propio; Pablo ve prudencia porque pide protección para sobrevivir. c) ¿Habría repartido la miel si no hubiera tormentas? d) Al comienzo pensaba que el zorro era egoísta; ahora pienso que es una mezcla de interés y de cuidado.",
   ["dos acuerdos", "desacuerdo con razones", "pregunta nueva", "cambio de postura explicado"], ["cierre escrito en el cuaderno"], ["cerrar con ganador", "pregunta cerrada", "no explicar el cambio"],
   "Verifica que tu cierre incluya las cuatro partes."),
  "Elige un tema y escribe un acuerdo, un desacuerdo razonado y una pregunta nueva.",
  "Explica por qué no hace falta que todos piensen igual para que un diálogo sea productivo.")
